function stripAlarmOkSuffix(v: string) { const t = String(v || "").trim(); return t.endsWith(" OK") ? t.slice(0, -3).trim() : t; }
function parseAlarmEnva(v: string) { return String(v || "").split(",").map(s => stripAlarmOkSuffix(s)).filter(s => s && s !== "-"); }
function formatAlarmEnvaForSave(v: string) { const names = parseAlarmEnva(v); if (names.length === 0) return "-"; return names.map(n => `${n} OK`).join(", "); }
function emptyRectifier(): RectifierForm { return { dcVoltage: "", loadCurrent: "", battOk: [{ type: "", qty: "" }], battNok: [{ type: "", qty: "" }], groupConfig: ["", "", "", ""], moduleOk: "", moduleNok: "", workMode: "", lvdPrio: "", lvdNonPrio: "", perangkatPrio: "", perangkatNonPrio: "" }; }
function batterySummary(slots: BatterySlot[]): string {
  const list = Array.isArray(slots) ? slots : [];
  if (list.some(s => s.type === "Tidak Ada Baterai")) return "Tidak Ada Baterai";
  const parts = list.filter(s => s.type).map(s => { const q = String(s.qty || "").trim(); return q ? `${q}x ${s.type}` : s.type; });
  return parts.join(" + ");
}
function batteryTotal(slots: BatterySlot[]): number { return (Array.isArray(slots) ? slots : []).reduce((s, x) => s + (parseInt(String(x.qty || "0"), 10) || 0), 0); }

