function resolveSiteMapping(rawId: string) {
  const id = String(rawId || "").trim().toUpperCase();
  const mapped = SITE_MAP[id];
  if (mapped) return { siteName: mapped.siteName, siteClass: mapped.siteClass, kabupaten: mapped.kabupaten, cluster: mapped.cluster, warning: null as string | null };
  const prefix = id.slice(0, 3);
  // Site ID di luar 79 entri lama tetap dikenali: Kabupaten / Cluster diturunkan
  // dari prefix (TDE / TER / LBA / COI) agar TIDAK pernah mengosongkan form
  // dan TIDAK memblokir simpan hanya karena ID belum ada di pemetaan lama.
  if (prefix === "TDE") return { siteName: "", siteClass: "", kabupaten: "KOTA TIDORE KEPULAUAN", cluster: "TIDORE", warning: null as string | null };
  if (prefix === "TER") return { siteName: "", siteClass: "", kabupaten: "KOTA TERNATE", cluster: "KOTA TERNATE TENGAH", warning: null as string | null };
  if (prefix === "LBA") return { siteName: "", siteClass: "", kabupaten: "HALMAHERA SELATAN", cluster: "OBI", warning: null as string | null };
  if (prefix === "COI") return { siteName: "", siteClass: "", kabupaten: "KOTA TERNATE", cluster: "KOTA TERNATE TENGAH", warning: null as string | null };
  if (!id) return { siteName: "", siteClass: "", kabupaten: "", cluster: "TO TERNATE / TIDORE", warning: null as string | null };
  if (id.length < 4) return { siteName: "", siteClass: "", kabupaten: "", cluster: "TO TERNATE / TIDORE", warning: null as string | null };
  return { siteName: "", siteClass: "", kabupaten: "", cluster: "TO TERNATE / TIDORE", warning: null as string | null };
}
// Daftar lengkap Site ID DATASITE / TIDORE DATABASE: 1.197 ID unik.
// TDE 001–800 (800) + TER 001–100 (100) + LBA 001–200 (200) + COI 001–097 (97) = 1.197.
// Entri lama (79) sudah termasuk di dalam rentang ini, jadi tidak ada duplikat.
// Nama / Class untuk ID di luar pemetaan lama diisi dari prefix saat dipilih,
// sehingga datalist tetap bisa dicari (ketik TDE009 langsung ketemu) dan form
// tidak pernah kosong hanya karena Sheet belum kebaca.
const ALL_SITE_IDS: string[] = (() => {
  const out: string[] = [];
  const pushRange = (prefix: string, from: number, to: number) => { for (let n = from; n <= to; n++) out.push(`${prefix}${String(n).padStart(3, "0")}`); };
  pushRange("TDE", 1, 800); pushRange("TER", 1, 100); pushRange("LBA", 1, 200); pushRange("COI", 1, 97);
  const seen = new Set(out);
  for (const id of Object.keys(SITE_MAP)) if (!seen.has(id)) { seen.add(id); out.push(id); }
  return out.sort();
})();
