const GPS_DENIED_MSG = "Izin lokasi ditolak. Aktifkan GPS / izin lokasi di browser, lalu tekan Deteksi Ulang Lokasi.";
type SiteCoord = { lat: number; lng: number };
// Koordinat site terdaftar (Latitude / Longitude) harus berasal dari DATASITE / DATALIST yang sah.
// Daftar ini sengaja tidak diisi dengan koordinat tebakan: tanpa koordinat resmi, deteksi tidak
// boleh mengarang site terdekat. Isi entri di bawah dari sumber resmi dengan bentuk
// TDE009: { lat: -0.123456, lng: 127.123456 } agar pencocokan Haversine bisa berjalan.
const SITE_COORDS: Record<string, SiteCoord> = {};
function haversineMeters(lat1: number, lng1: number, lat2: number, lng2: number) {
  const R = 6371000; const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1); const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return 2 * R * Math.asin(Math.sqrt(a));
}
function findNearestSite(lat: number, lng: number) {
  let best: { siteId: string; distanceM: number } | null = null;
  for (const siteId of Object.keys(SITE_COORDS)) {
    if (!SITE_MAP[siteId]) continue;
    const d = haversineMeters(lat, lng, SITE_COORDS[siteId].lat, SITE_COORDS[siteId].lng);
    if (!best || d < best.distanceM) best = { siteId, distanceM: d };
  }
  return best;
}
