function normStatus(s: string) { return String(s || "").trim().toUpperCase(); }
function firstWord(v: string) { return String(v || "").trim().toLowerCase().split(/\s+/)[0] || ""; }
function splitPicNames(pic: string) { return String(pic || "").split(/\s*(?:\/|,|&|\bdan\b)\s*/i).map(s => s.trim()).filter(Boolean); }
function isSuperadminUser(username: string) { return firstWord(username) === "superadmin"; }
function isAdminUser(username: string) { const u = firstWord(username); return u === "admin" || u === "moti" || u === "semua" || u === "superadmin"; }
function picMatchesUser(pic: string, username: string) { if (isAdminUser(username)) return true; const userFirst = firstWord(username); if (!userFirst) return false; return splitPicNames(pic).some(part => firstWord(part) === userFirst); }
function sheetTaskKey(t: SheetTask) { return `${t.siteId || ""}|${t.siteName || ""}`; }
function historyRecordId() { return `H${Date.now()}${Math.random().toString(36).slice(2, 8).toUpperCase()}`; }
function normHistoryStatus(s: string | undefined | null) { const v = String(s || "").trim().toUpperCase(); if (v === "BERHASIL" || v === "VALID" || v === "SUCCESS" || v === "SELESAI" || v === "") return "DONE"; if (v === "DONE" || v === "CLOSED" || v === "DITOLAK") return v; return "DONE"; }
