  function clearAuditPowerForm() { setAuditPowerForm({ ...EMPTY_AUDIT, inputBy: selectedPic, rectifiers: [emptyRectifier()] }); setSiteWarning(null); }
  function validateAuditPower(): string | null {
    if (!auditPowerForm.siteId.trim()) return "Isi Site ID terlebih dahulu.";
    for (let i = 0; i < auditPowerForm.rectifiers.length; i++) { const r = auditPowerForm.rectifiers[i]; for (let g = 0; g < 4; g++) { const v = String(r.groupConfig[g] || "").trim(); if (v && !GROUP_VALUES.includes(v)) return `Rectifier ${i + 1} Group ${g + 1}: hanya boleh 0, 100, 200, 300, 400, 500, 800. Selain itu tidak bisa disimpan.`; } }
    return null;
  }
  async function submitAuditPower(e: React.FormEvent) {
    e.preventDefault();
    const err = validateAuditPower();
    if (err) { setSaveMsg(err); return; }
    setShowAuditConfirm(true);
  }
  async function confirmSaveAuditPower() {
    setShowAuditConfirm(false);
    const err = validateAuditPower();
    if (err) { setSaveMsg(err); return; }
    const submitNow = nowWita(); const submitLabel = fmtSubmitDate(submitNow);
    const value: AuditSheet = { ...auditPowerForm, alarmEnva: formatAlarmEnvaForSave(auditPowerForm.alarmEnva), rectifiers: auditPowerForm.rectifiers.slice(0, parseInt(auditPowerForm.jmlRect, 10) || 1), timestamp: submitNow.toISOString(), tanggal: submitLabel, inputBy: selectedPic, createdAt: new Date().toISOString() };
    const tsv = auditToTSV(value);
    setAuditSheetError(null); setSaveMsg("Menyimpan…"); setLastSheetStatus("Mengirim… — menunggu jawaban penyimpanan, belum tampil Berhasil.");
    const rowNumber = auditTotal + 1;
    const successMsg = `Data Berhasil Disimpan — Sheet: AUDIT, baris: ${rowNumber}`;
    setRowPreview(tsv); setCopiedRow(false);
    try { await saveWithHistory([{ collection: "office_audit_power", value }, { collection: "office_history", value: { type: "Audit Power", title: `Audit Power ${value.siteName} • ${value.siteId}`, desc: `Sheet TIDORE • Input By ${value.inputBy} • ${value.tanggal} • Alarm ENVA: ${value.alarmEnva}`, time: fmtShort(nowWita()), category: "Audit Power", createdAt: new Date().toISOString(), siteId: value.siteId, siteName: value.siteName, alarmEnva: value.alarmEnva } }]); } catch (e: any) { const msg = `Gagal menyimpan Audit: ${e?.message || "Penyimpanan gagal"} — form tidak dibersihkan, coba lagi.`; setAuditSheetError(msg); setSaveMsg(msg); setNotice(msg); setLastSheetStatus(msg); return; }
    clearAuditPowerForm();
    setLastSheetStatus(`Terakhir: success - ${successMsg}`);
    setSaveMsg(successMsg);
    setNotice(successMsg);
  }
  async function retrySaveAuditPower() { if (retryingAudit) return; setRetryingAudit(true); try { await confirmSaveAuditPower(); } finally { setRetryingAudit(false); } }
  function copyAuditRow() { if (!rowPreview) return; const el = previewRef.current; if (el) { el.focus(); el.select(); try { document.execCommand("copy"); setCopiedRow(true); setSaveMsg("Baris berhasil disalin. Tempel ke baris baru di Sheet TIDORE DATABASE."); } catch { setSaveMsg("Gagal menyalin otomatis. Blok teks di kotak preview lalu salin manual."); } } }

  async function submitProject(e: React.FormEvent) { e.preventDefault(); if (!projectForm.name.trim() || !projectForm.pic.trim() || !projectForm.deadline) { setNotice("Lengkapi nama tugas, PIC, dan deadline."); return; } const value = { ...projectForm, desc: projectForm.desc || "—", status: projectForm.progress >= 100 ? "Selesai" : "Berjalan", createdAt: new Date().toISOString() }; let saved = 0; try { saved = await saveWithHistory([{ collection: "office_projects", value }, { collection: "office_history", value: { type: "Tugas", title: `Tugas baru: ${value.name}`, desc: `PIC ${value.pic} • Target ${value.progress}%`, time: fmtShort(nowWita()), category: "Tugas", createdAt: new Date().toISOString() } }]); } catch (err: any) { setNotice(`Gagal simpan ke Google Sheet: ${err?.message || "Penyimpanan gagal"} — cek URL Apps Script & deployment Anyone`); return; } if (saved >= 2) { setNotice("Tugas berhasil disimpan."); setShowProjectForm(false); goToTab("project"); setProjectForm({ name: "", desc: "", pic: "", deadline: "", progress: 10 }); } else { setNotice("Gagal simpan ke Google Sheet: tidak semua baris tersimpan — cek URL Apps Script & deployment Anyone"); } }
  async function submitInventory(e: React.FormEvent) { e.preventDefault(); if (!invForm.name.trim() || !invForm.sheetId.trim()) { setNotice("Lengkapi ID dan Nama Barang."); return; } const value: SheetBarang = { sheetId: invForm.sheetId.trim().toUpperCase(), name: invForm.name.trim().toUpperCase(), category: invForm.category, unit: invForm.unit.trim().toUpperCase() || "PCS", stock: invForm.stock, minStock: invForm.minStock, createdAt: new Date().toISOString() }; let saved = 0; try { saved = await saveWithHistory([{ collection: "office_inventory_sheet", value }, { collection: "office_history", value: { type: "Inventory", title: `Item baru: ${value.name}`, desc: `${value.sheetId} • Stok ${value.stock} ${value.unit} • ${value.category}`, time: fmtShort(nowWita()), category: "Inventory", createdAt: new Date().toISOString() } }]); } catch (err: any) { setNotice(`Gagal simpan ke Google Sheet: ${err?.message || "Penyimpanan gagal"} — cek URL Apps Script & deployment Anyone`); return; } if (saved >= 2) { setNotice("Barang berhasil disimpan."); setShowInventoryForm(false); goToTab("inventory"); setInvForm({ sheetId: "", name: "", category: "OK", unit: "PCS", stock: 1, minStock: 5 }); } else { setNotice("Gagal simpan ke Google Sheet: tidak semua baris tersimpan — cek URL Apps Script & deployment Anyone"); } }
  async function handleCheckIn() { const isAdmin = isAdminUser(selectedPic); const siteId = ciSiteId.trim().toUpperCase() || (isAdmin ? "ADMIN" : ""); if (!isAdmin && gpsStatus === "detecting") { setNotice("Mendeteksi lokasi... Tunggu sampai GPS aktif, lalu tekan Check-IN lagi."); return; } if (!isAdmin && gpsStatus === "outside") { setNotice(`Check-IN ditolak — di luar area site. Site terdekat ${gpsNearestId || siteId} jarak ${gpsDistanceM != null ? Math.round(gpsDistanceM) + " m" : "—"} (maks 200 m). Dekati site lalu tekan Cari Lokasi Saya lagi.`); return; } if (!isAdmin && (gpsStatus === "denied" || gpsStatus === "unsupported")) { setNotice(gpsMessage || GPS_DENIED_MSG); return; } if (!isAdmin && gpsLat == null) { setNotice("Aktifkan GPS dulu — tekan tombol Cari Lokasi Saya / Aktifkan GPS sampai lokasi ketemu, baru tekan Check-IN."); return; } if (!isAdmin && !siteId) { setNotice("Site ID belum terisi. Setelah GPS aktif, pilih Site ID dari daftar 1.197 Site ID karena koordinat resmi site belum terdaftar, lalu tekan Check-IN."); return; } const already = siteId === "ADMIN" && isAdmin ? checkins.some(c => c.value.date === todayKey && checkinSiteOf(c) === "ADMIN" && String(c.value.pic || "").trim().toLowerCase() === selectedPic.trim().toLowerCase()) : checkins.some(c => c.value.date === todayKey && checkinSiteOf(c) === siteId && (!String(c.value.pic || "").trim() || String(c.value.pic || "").trim().toLowerCase() === selectedPic.trim().toLowerCase())); if (already) { setNotice("Sudah Check-IN hari ini di site ini. Checking cukup 1x sehari."); return; } const value = { date: todayKey, location: siteId, siteId, pic: selectedPic, shift: "", note: ciNote || "—", checkIn: fmtShort(now), checkOut: "", durationMin: 0, status: "Masuk", createdAt: new Date().toISOString(), lat: gpsLat ?? undefined, lng: gpsLng ?? undefined, distanceM: gpsDistanceM != null ? Math.round(gpsDistanceM) : undefined }; setCheckinSheetStatus("Mengirim Check-IN… — menunggu jawaban penyimpanan, belum tampil Berhasil.");
    let saved = 0; try { saved = await saveWithHistory([{ collection: "office_checkins", value }, { collection: "office_history", value: { type: "Check-In", title: "Check-In berhasil", desc: `${siteId} • PIC ${selectedPic} • Masuk ${value.checkIn}${gpsDistanceM != null ? ` • Jarak ${Math.round(gpsDistanceM)} m` : ""}`, time: fmtShort(now), category: "Check-In", createdAt: new Date().toISOString(), status: "DONE", approvalBy: "", approvalAt: "" } }]); } catch (err: any) { const msg = `Gagal menyimpan Check-IN: ${err?.message || "Penyimpanan gagal"}`; setCheckinSheetStatus(msg); setNotice(msg); return; } if (saved >= 2) { setCheckinSheetStatus(`Terakhir: success - Check-IN tersimpan`); setLastSheetStatus(`Terakhir: success - Check-IN`); setNotice(`Check-In tercatat pukul ${value.checkIn}. Selamat bekerja!`); setCiNote(""); } else { setNotice("Gagal menyimpan Check-IN: tidak semua baris tersimpan."); } }
  async function adjustStock(item: Rec<SheetBarang>, delta: number) { const next = Math.max(0, item.value.stock + delta); setBusy(true); try { await api("records.replace", { collection: "office_inventory_sheet", id: item.id, value: { ...item.value, stock: next } }); await createRow("office_inventory_txns", { txnId: `TRX-${Date.now()}`, date: fmtSubmitDate(nowWita()), type: delta >= 0 ? "MASUK" : "KELUAR", itemName: item.value.name, qty: Math.abs(delta), recipient: "—", note: `Penyesuaian stok ${item.value.stock} → ${next}`, admin: selectedPic, createdAt: new Date().toISOString() }); await createRow("office_history", { type: "Inventory", title: `Stok ${item.value.name} diubah`, desc: `${item.value.stock} → ${next} • ${item.value.sheetId}`, time: fmtShort(now), category: "Inventory", createdAt: new Date().toISOString(), id: historyRecordId(), status: "DONE", approvalBy: "", approvalAt: "" }); await reloadRecords(); setNotice(`Stok ${item.value.name} menjadi ${next}.`); } catch (e: any) { setNotice(e.message); } setBusy(false); }
  async function deleteInventory(item: Rec<SheetBarang>) { setBusy(true); try { await api("records.delete", { collection: "office_inventory_sheet", id: item.id }); await reloadRecords(); setNotice("Item inventory dihapus."); } catch (e: any) { setNotice(e.message); } setBusy(false); }
  async function updateProject(p: Rec<Project>, progress: number) { const prog = Math.max(0, Math.min(100, progress)); const status = prog >= 100 ? "Selesai" : prog === 0 ? "Tertunda" : "Berjalan"; setBusy(true); try { await api("records.replace", { collection: "office_projects", id: p.id, value: { ...p.value, progress: prog, status } }); await reloadRecords(); setNotice(`${p.value.name}: progress ${prog}%.`); } catch (e: any) { setNotice(e.message); } setBusy(false); }
  async function deleteProject(p: Rec<Project>) { setBusy(true); try { await api("records.delete", { collection: "office_projects", id: p.id }); await reloadRecords(); setNotice("Tugas dihapus."); } catch (e: any) { setNotice(e.message); } setBusy(false); }
  const filteredAudits = audits.filter(a => (auditFilter === "Semua" || a.value.condition === auditFilter) && (a.value.device + a.value.location + a.value.findings).toLowerCase().includes(auditSearch.toLowerCase())).sort((a, b) => b.value.createdAt.localeCompare(a.value.createdAt));
  const filteredProjects = projects.filter(p => (projFilter === "Semua" || p.value.status === projFilter) && (p.value.name + p.value.pic).toLowerCase().includes(projSearch.toLowerCase())).sort((a, b) => b.value.createdAt.localeCompare(a.value.createdAt));
  const filteredInv = inventory.filter(i => (invFilter === "Semua" || i.value.category.toUpperCase() === invFilter) && (i.value.name + " " + i.value.sheetId).toLowerCase().includes(invSearch.toLowerCase())).sort((a, b) => a.value.name.localeCompare(b.value.name));
  const sortedTxns = [...inventoryTxns].sort((a, b) => b.value.createdAt.localeCompare(a.value.createdAt)).slice(0, 10);
  const invSyncLabel = invLastSync ? fmtTime(invLastSync) : "Belum disinkron";
  const historyDoneCount = history.filter(r => normHistoryStatus(r.value.status) === "DONE").length;
  const historyClosedCount = history.filter(r => normHistoryStatus(r.value.status) === "CLOSED").length;
  const historyRejectedCount = history.filter(r => normHistoryStatus(r.value.status) === "DITOLAK").length;
  const monthKey = todayKey.slice(0, 7); const monthHist = history.filter(r => String(r.value.createdAt || "").slice(0, 7) === monthKey); const monthClosed = monthHist.filter(r => normHistoryStatus(r.value.status) === "CLOSED").length; const monthPending = monthHist.filter(r => normHistoryStatus(r.value.status) === "DONE").length;
  const filteredHist = sortedHistory.filter(h => { if (historyFilter === "DONE Menunggu" && normHistoryStatus(h.value.status) !== "DONE") return false; if (historyFilter === "CLOSED Disetujui" && normHistoryStatus(h.value.status) !== "CLOSED") return false; if (historyFilter === "DITOLAK" && normHistoryStatus(h.value.status) !== "DITOLAK") return false; if (histPicFilter !== "Semua") { const hay = `${h.value.title} ${h.value.desc}`.toLowerCase(); const first = firstWord(histPicFilter); if (!hay.includes(first)) return false; } if (histDateFilter) { const created = String(h.value.createdAt || "").slice(0, 10); if (created !== histDateFilter) return false; } return (histFilter === "Semua" || h.value.type === histFilter || h.value.category === histFilter || (histFilter === "Tugas" && (h.value.type === "Project" || h.value.category === "Project"))) && (h.value.title + h.value.desc).toLowerCase().includes(histSearch.toLowerCase()); });
  const nav: { id: Tab; label: string; icon: any }[] = [{ id: "dashboard", label: "Beranda", icon: LayoutDashboard }, { id: "audit", label: "Audit Power", icon: Zap }, { id: "checkin", label: "Check-IN", icon: Clock }, { id: "history", label: "History", icon: HistoryIcon }, { id: "project", label: "Tugas", icon: FolderKanban }, { id: "inventory", label: "Inventory", icon: Package }];
  const conditionStyle = (c: string) => c === "Baik" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : c === "Perlu Perbaikan" ? "bg-amber-50 text-amber-700 border-amber-200" : "bg-red-50 text-red-700 border-red-200";
  const stockLabel = (i: SheetBarang) => i.stock === 0 ? "Stok Habis" : i.stock < i.minStock ? "Stok Menipis / Perlu Restock" : "Stok Aman";
  const stockStyle = (i: SheetBarang) => i.stock === 0 ? "bg-red-50 text-red-700 border-red-200" : i.stock < i.minStock ? "bg-red-50 text-red-700 border-red-200" : "bg-emerald-50 text-emerald-700 border-emerald-200";
  // Satu jalur navigasi untuk nav atas, bottom nav, dan semua tombol di Dashboard.
