  function goToTab(next: Tab) { if (next !== "checkin" && next !== "dashboard" && isMenuLocked) { setTab("checkin"); setNotice(LOCK_MESSAGE); setNavTick(t => t + 1); return; } setTab(next); setNotice(null); setNavTick(t => t + 1); }
  useEffect(() => { if (loading) return; if (isMenuLocked && tab !== "checkin" && tab !== "dashboard") { setTab("checkin"); setNotice(LOCK_MESSAGE); setNavTick(t => t + 1); } }, [isMenuLocked, loading, tab]);
