          <div className="flex items-center justify-between gap-2"><div className="flex items-center gap-3 min-w-0"><div className="w-11 h-11 rounded-[10px] bg-white grid place-items-center shrink-0 shadow" aria-label="Logo MOTI"><span className="leading-none text-center"><span className="block text-[22px] font-extrabold leading-none text-[#E60000]">M</span><span className="block text-[8px] font-extrabold tracking-widest text-[#E60000]">MOTI</span></span></div><div className="min-w-0"><p className="text-[24px] font-extrabold leading-tight truncate text-white">MOTI</p><p className="text-[11px] text-white/90 truncate font-semibold">Monitoring Operation and Territory</p></div></div><div className="w-9 h-9 rounded-full bg-white/25 text-white grid place-items-center font-extrabold text-sm shrink-0" aria-label="Avatar S">S</div></div>
